windowclass.script:
function onInit()
				if Checkbox11 then
					Checkbox11.setVisible(false);
				end

				if Checkbox12 then
					Checkbox12.setVisible(false);
				end

				if Checkbox13 then
					Checkbox13.setVisible(false);
				end

				if Checkbox14 then
					Checkbox14.setVisible(false);
				end

				if Checkbox15 then
					Checkbox15.setVisible(false);
				end

				if Checkbox16 then
					Checkbox16.setVisible(false);
				end

				if Checkbox17 then
					Checkbox17.setVisible(false);
				end

				if Checkbox18 then
					Checkbox18.setVisible(false);
				end
			end

buttonfield.script:
function getActorNode()
						local node = window.getDatabaseNode();

						while node do
							if DB.getValue(node, "name", "") ~= "" then
								return node;
							end

							node = node.getParent();
						end

						return nil;
					end

					function getActorNameFromNode(nodeActor)
						if not nodeActor then
							return "Unknown Actor";
						end

						local rActor = ActorManager.resolveActor(nodeActor);
						if rActor then
							return ActorManager.getDisplayName(rActor);
						end

						return DB.getValue(nodeActor, "name", "Unknown Actor");
					end

					function getModifierText(nMod)
						if nMod >= 0 then
							return "+" .. nMod;
						end

						return tostring(nMod);
					end

					function sendModMessageToAll(sText)
						local msg = {};
						msg.font = "systemfont";
						msg.text = sText;

						Comm.deliverChatMessage(msg);
					end

					function onClickDown(button, x, y)
						-- Only fire when currently unchecked.
						-- Since this runs before FG toggles the checkbox,
						-- getValue() == 0 means the click is checking it.
						if getValue() ~= 0 then
							return true;
						end

						local sCheckboxName = getName();

						-- Example: Checkbox1 -> StringField1
						local sStringFieldName = sCheckboxName:gsub("Checkbox", "StringField");

						local sModName = "P";

						if window[sStringFieldName] then
							sModName = window[sStringFieldName].getValue();
						end

						if not sModName or sModName == "" then
							sModName = sCheckboxName;
						end

						local nodeActor = getActorNode();

						local sActorName = getActorNameFromNode(nodeActor);
						local sActorNode = "";

						if nodeActor then
							sActorNode = nodeActor.getPath();
						end

						local nMod = 1;

						ModifierStack.addSlot(sModName, nMod);

						local msgOOB = {};
						msgOOB.type = "themecheckboxmod";
						msgOOB.sActorName = sActorName;
						msgOOB.sActorNode = sActorNode;
						msgOOB.sModName = sModName;
						msgOOB.nMod = nMod;

						if Session.IsHost then
							sendModMessageToAll(sActorName .. " added " .. getModifierText(nMod) .. " from " .. sModName);
						else
							Comm.deliverOOBMessage(msgOOB, "");
						end

						-- Important: allow the checkbox to still toggle normally
						return true;
					end

